#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include "kernel.h"

// Destination-passing-style entry for the Whisper decoder output
// projection. Per definition.json:
//   hidden_states : [batch_size, seq_len, d_model=1280] fp16
//   weight        : [vocab_size=51866, d_model=1280]    fp16
//   logits        : [batch_size, seq_len, vocab_size=51866] fp16 (DPS)
//
// Const axes pinned by the problem definition AND enforced on every
// tensor the kernel indexes with that fixed assumption, following
// the runtime-check audit discipline:
//   d_model    = 1280   pinned on hidden_states and weight.
//   vocab_size = 51866  pinned on weight and logits.
//
// The kernel reduces the 3D `[B, S, *]` tensors to flat 2D
// `[B*S, *]` views via `flatten(0, 1)` before calling the launcher;
// the launcher emits a single CUTLASS Sm80 TensorOp GEMM with
// `M = B*S`, `K = d_model = 1280`, `N = vocab_size = 51866`,
// `AlignmentC = 2` (since 51866 mod 8 = 2).

void run(
    torch::Tensor hidden_states,
    torch::Tensor weight,
    torch::Tensor logits
) {
    TORCH_CHECK(hidden_states.is_cuda(), "hidden_states must be CUDA");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
    TORCH_CHECK(logits.is_cuda(), "logits must be CUDA");

    TORCH_CHECK(hidden_states.dtype() == torch::kFloat16,
                "hidden_states must be float16");
    TORCH_CHECK(weight.dtype() == torch::kFloat16,
                "weight must be float16");
    TORCH_CHECK(logits.dtype() == torch::kFloat16,
                "logits must be float16");

    TORCH_CHECK(hidden_states.is_contiguous(),
                "hidden_states must be contiguous");
    TORCH_CHECK(weight.is_contiguous(), "weight must be contiguous");
    TORCH_CHECK(logits.is_contiguous(), "logits must be contiguous");

    TORCH_CHECK(hidden_states.dim() == 3,
                "hidden_states must be 3D [B, S, d_model]");
    TORCH_CHECK(weight.dim() == 2,
                "weight must be 2D [vocab_size, d_model]");
    TORCH_CHECK(logits.dim() == 3,
                "logits must be 3D [B, S, vocab_size]");

    constexpr int64_t kDModel = 1280;
    constexpr int64_t kVocabSize = 51866;

    TORCH_CHECK(hidden_states.size(2) == kDModel,
                "hidden_states.size(2) must equal d_model=1280, got ",
                hidden_states.size(2));
    TORCH_CHECK(weight.size(1) == kDModel,
                "weight.size(1) must equal d_model=1280, got ",
                weight.size(1));
    TORCH_CHECK(weight.size(0) == kVocabSize,
                "weight.size(0) must equal vocab_size=51866, got ",
                weight.size(0));
    TORCH_CHECK(logits.size(2) == kVocabSize,
                "logits.size(2) must equal vocab_size=51866, got ",
                logits.size(2));
    TORCH_CHECK(logits.size(0) == hidden_states.size(0),
                "logits.size(0) must equal hidden_states.size(0)");
    TORCH_CHECK(logits.size(1) == hidden_states.size(1),
                "logits.size(1) must equal hidden_states.size(1)");

    auto hidden_states_2d = hidden_states.flatten(0, 1);
    auto logits_2d = logits.flatten(0, 1);

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    problem_077_whisper_decoder_output_projection_launcher(
        hidden_states_2d, weight, logits_2d, stream);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def(
        "run", &run,
        "fp16 GEMM logits = hidden_states @ weight.T via CUTLASS "
        "TensorOp on Sm80; destination-passing style. d_model=1280, "
        "vocab_size=51866 pinned; AlignmentC=2 epilogue.");
}

#include "kernel.h"

#include <cutlass/gemm/device/gemm.h>
#include <cutlass/numeric_types.h>
#include <cutlass/layout/matrix.h>
#include <cutlass/arch/arch.h>
#include <cutlass/arch/mma.h>
#include <cutlass/epilogue/thread/linear_combination.h>

// fp16 GEMM with fp32 accumulation: logits = hidden_states @ weight^T.
//
// Same row-major-to-mixed-layout encoding as the landed
// problem_004 / problem_007 / problem_008 / problem_009 /
// problem_010 / problem_011 GEMM cohort:
//   A (hidden_states): [M, K] row-major  -> RowMajor    with lda = K.
//   B (weight):        [N, K] row-major  -> ColumnMajor with ldb = K
//       (this is B^T col-major [K, N]).
//   C (logits):        [M, N] row-major  -> RowMajor    with ldc = N.
//
// Const axes pinned by the problem definition:
//   d_model    = K = 1280
//   vocab_size = N = 51866
//
// 51866 mod 8 = 2 -> the default `LinearCombination<half_t, 8, ...>`
// epilogue (AlignmentC = 8) would fail at kernel-init or produce
// out-of-bounds stores on the tail tile. Use `AlignmentC = 2`
// (LinearCombination kCount = 2) for a contract-faithful vector
// width that still satisfies 51866 mod 2 = 0.
//
// AlignmentA / AlignmentB stay at the default 8 (K = 1280 is
// 8-element aligned: 1280 mod 8 = 0).

namespace {

using ElementInputA = cutlass::half_t;
using ElementInputB = cutlass::half_t;
using ElementOutput = cutlass::half_t;
using ElementAccumulator = float;

using LayoutInputA = cutlass::layout::RowMajor;
using LayoutInputB = cutlass::layout::ColumnMajor;
using LayoutOutput = cutlass::layout::RowMajor;

using MMAOp = cutlass::arch::OpClassTensorOp;
using SmArch = cutlass::arch::Sm80;

using ThreadblockShape = cutlass::gemm::GemmShape<128, 128, 32>;
using WarpShape = cutlass::gemm::GemmShape<64, 64, 32>;
using InstructionShape = cutlass::gemm::GemmShape<16, 8, 16>;

constexpr int kAlignmentC = 2;

using EpilogueOp = cutlass::epilogue::thread::LinearCombination<
    ElementOutput,
    kAlignmentC,
    ElementAccumulator,
    ElementAccumulator>;

using SwizzleThreadBlock =
    cutlass::gemm::threadblock::GemmIdentityThreadblockSwizzle<>;
constexpr int kNumStages = 3;

using CutlassGemm = cutlass::gemm::device::Gemm<
    ElementInputA, LayoutInputA,
    ElementInputB, LayoutInputB,
    ElementOutput, LayoutOutput,
    ElementAccumulator,
    MMAOp,
    SmArch,
    ThreadblockShape,
    WarpShape,
    InstructionShape,
    EpilogueOp,
    SwizzleThreadBlock,
    kNumStages>;

}  // namespace

void problem_077_whisper_decoder_output_projection_launcher(
    const torch::Tensor& hidden_states_2d,
    const torch::Tensor& weight,
    torch::Tensor& logits_2d,
    cudaStream_t stream) {

    const int M = static_cast<int>(hidden_states_2d.size(0));
    const int K = static_cast<int>(hidden_states_2d.size(1));
    const int N = static_cast<int>(weight.size(0));

    auto const* A_ptr = reinterpret_cast<ElementInputA const*>(
        hidden_states_2d.data_ptr<at::Half>());
    auto const* B_ptr = reinterpret_cast<ElementInputB const*>(
        weight.data_ptr<at::Half>());
    auto* C_ptr = reinterpret_cast<ElementOutput*>(
        logits_2d.data_ptr<at::Half>());

    CutlassGemm gemm_operator;

    CutlassGemm::Arguments args(
        {M, N, K},
        {A_ptr, K},
        {B_ptr, K},
        {C_ptr, N},
        {C_ptr, N},
        {1.0f, 0.0f});

    cutlass::Status status = gemm_operator(args, nullptr, stream);
    TORCH_CHECK(
        status == cutlass::Status::kSuccess,
        "CUTLASS GEMM (problem_077) failed: ",
        cutlassGetStatusString(status));
}

#pragma once

#include <torch/extension.h>
#include <cuda_runtime.h>

// Host launcher for the Whisper decoder output projection GEMM:
//   logits = hidden_states @ weight^T
//
// hidden_states: [M, K=1280] fp16 row-major (flattened from
//                [B, S, d_model] with M = B*S).
// weight:        [N=51866, K=1280] fp16 row-major.
// logits:        [M, N=51866] fp16 row-major
//                (destination-passing-style; pre-allocated by the
//                eval driver, flattened from [B, S, vocab_size]).
//
// N = vocab_size = 51866 and K = d_model = 1280 are pinned by the
// problem definition; M varies per workload. N=51866 is NOT 8-element
// aligned (51866 mod 8 = 2), so the epilogue uses AlignmentC = 2
// instead of the default 8.
void problem_077_whisper_decoder_output_projection_launcher(
    const torch::Tensor& hidden_states_2d,
    const torch::Tensor& weight,
    torch::Tensor& logits_2d,
    cudaStream_t stream);
